async def act(page):
    """
    Continue from the current "Create Product Settings" screen and create a simple product:
    - Close any blocking popup if present.
    - Click Continue (using full table->row->button path as shown in the accessibility tree).
    - Fill product fields: Name, SKU, Price.
    - Open Inventory tab and set Qty = 50 and mark In Stock.
    - Select Size = S and Color = Blue (via combobox select_option).
    - Click Save (final action).
    """

    # Helper utilities
    async def safe_click(locator):
        try:
            if await locator.count() > 0:
                await locator.click()
                return True
        except Exception:
            return False
        return False

    async def try_fill_textbox(value, *names):
        for n in names:
            try:
                tb = page.get_by_role("textbox", name=n)
                if await tb.count() > 0:
                    await tb.fill(value)
                    return True
            except Exception:
                continue
        return False

    async def try_select_combobox(locator, *labels):
        for lbl in labels:
            try:
                await locator.select_option(label=lbl)
                return True
            except Exception:
                try:
                    await locator.select_option(value=lbl)
                    return True
                except Exception:
                    continue
        return False

    # 0) Attempt to close any blocking popup that may prevent interacting with the page.
    # Try several common close button names and then scan aria-label for 'close'.
    for name in ("Close", "close", "×", "X", "Dismiss", "dismiss"):
        try:
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                await btn.click()
                await page.wait_for_timeout(300)
                break
        except Exception:
            pass

    try:
        # scan buttons for aria-label containing 'close'
        all_buttons = page.get_by_role("button")
        for i in range(await all_buttons.count()):
            b = all_buttons.nth(i)
            try:
                label = await b.get_attribute("aria-label")
                if label and "close" in label.lower():
                    await b.click()
                    await page.wait_for_timeout(300)
                    break
            except Exception:
                continue
    except Exception:
        pass

    # 1) Click Continue using the full get_by_role path from the accessibility tree:
    # table -> row "Continue" -> button "Continue"
    try:
        table = page.get_by_role("table")
        row = table.get_by_role("row", name="Continue")
        continue_btn = row.get_by_role("button", name="Continue")
        if await continue_btn.count() > 0:
            await continue_btn.click()
            # Wait for the product form to load
            try:
                await page.wait_for_load_state("networkidle", timeout=10000)
            except Exception:
                await page.wait_for_timeout(1200)
        else:
            # fallback: any Continue button
            cont = page.get_by_role("button", name="Continue")
            if await cont.count() > 0:
                await cont.click()
                try:
                    await page.wait_for_load_state("networkidle", timeout=10000)
                except Exception:
                    await page.wait_for_timeout(1200)
    except Exception:
        # if something goes wrong, continue anyway to attempts to fill fields
        pass

    # Small pause to ensure form fields are present
    await page.wait_for_timeout(500)

    # 2) Fill main product fields
    # Name (try several common accessible labels)
    await try_fill_textbox("Energy-Bulk Women Shirt", "Name", "Product Name", "name")
    # SKU
    await try_fill_textbox("ENERGY-BULK-W-S", "SKU", "sku")
    # Price
    await try_fill_textbox("60", "Price", "price")

    # 3) Inventory tab: attempt to open then set Qty and In Stock
    try:
        inv_tab = page.get_by_role("tab", name="Inventory")
        if await inv_tab.count() > 0:
            await inv_tab.click()
            await page.wait_for_timeout(300)
    except Exception:
        try:
            stock_tab = page.get_by_role("tab", name="Stock")
            if await stock_tab.count() > 0:
                await stock_tab.click()
                await page.wait_for_timeout(300)
        except Exception:
            pass

    # Fill quantity
    await try_fill_textbox("50", "Qty", "Quantity", "qty", "Quantity In Stock")

    # Set In Stock via combobox selection (try common labels)
    try:
        combs = page.get_by_role("combobox")
        for i in range(await combs.count()):
            cb = combs.nth(i)
            if await try_select_combobox(cb, "In Stock", "Yes", "1"):
                break
    except Exception:
        pass

    # 4) Select Size = S and Color = Blue
    try:
        size_cb = page.get_by_role("combobox", name="Size")
        if await size_cb.count() > 0:
            await try_select_combobox(size_cb, "S", "Small")
        else:
            combs = page.get_by_role("combobox")
            for i in range(await combs.count()):
                cb = combs.nth(i)
                if await try_select_combobox(cb, "S", "Small"):
                    break
    except Exception:
        pass

    try:
        color_cb = page.get_by_role("combobox", name="Color")
        if await color_cb.count() > 0:
            await try_select_combobox(color_cb, "Blue", "blue")
        else:
            combs = page.get_by_role("combobox")
            for i in range(await combs.count()):
                cb = combs.nth(i)
                if await try_select_combobox(cb, "Blue", "blue"):
                    break
    except Exception:
        pass

    await page.wait_for_timeout(500)

    # 5) Click Save (final action). Use role-based lookup for Save button.
    try:
        save_btn = page.get_by_role("button", name="Save")
        if await save_btn.count() > 0:
            await save_btn.click()
            try:
                await page.wait_for_load_state("networkidle", timeout=10000)
            except Exception:
                await page.wait_for_timeout(2000)
        else:
            # fallback: search inside groups for a Save button
            groups = page.get_by_role("group")
            for i in range(await groups.count()):
                grp = groups.nth(i)
                btn = grp.get_by_role("button", name="Save")
                if await btn.count() > 0:
                    await btn.click()
                    try:
                        await page.wait_for_load_state("networkidle", timeout=10000)
                    except Exception:
                        await page.wait_for_timeout(2000)
                    break
    except Exception:
        pass

